    "每个信号按其比率与本项赛事联赛平均值的差距打分，并按样本量加权（n/(n+5)）。不足五场永远不参与排序——短暂的连续是背景，不是发现。没有联赛基准的市场绝不与编造的数字比较；它归入下方的完整明细。最强的信号只有越过固定门槛才会领衔页面；若无一越过，页面便没有核心发现，而不是编造一个。",
